old_feeder:
always @(posedge clk)begin
 if(reset||cancel)begin byte_valid<=0;byte_data<=0;end
 else if(state==RUN)begin
  if(!byte_valid&&bytes_sent<FIXTURE_BYTES)begin
   byte_data<=rom[bytes_sent];byte_valid<=1;
  end else if(byte_valid&&ki)byte_valid<=0;
 end else byte_valid<=0;
end

new_feeder:
wire fixture_fetch_enable=!reset&&!cancel&&state==RUN&&!byte_valid&&bytes_sent<FIXTURE_BYTES;
// Never reset the ROM data output: reset/cancel invalidate ownership only.
// All inferred ROM ports must remain disabled before the reset fence opens.
always @(posedge clk)if(fixture_fetch_enable)byte_data<=rom[bytes_sent];
always @(posedge clk)begin
 if(reset||cancel)byte_valid<=0;
 else if(state==RUN)begin
  if(!byte_valid&&bytes_sent<FIXTURE_BYTES)byte_valid<=1;
  else if(byte_valid&&ki)byte_valid<=0;
 end else byte_valid<=0;
end
